# -*- coding: utf-8 -*-
import sys, io, os, zipfile
sys.path.insert(0, r"F:\@AI-workshop\rwmod")
import rwmod_tool as T

out = io.open(r"C:\Users\33406\AppData\Local\Temp\opencode\diag8_out.txt", "w", encoding="utf-8")
def w(*a): out.write(" ".join(str(x) for x in a) + "\n")
def vis(s):
    r=[]
    for ch in s:
        o=ord(ch)
        if ch=="\r": r.append("\\r")
        elif ch=="\n": r.append("\\n")
        elif ch=="\t": r.append("\\t")
        elif 0x20<=o<0x7f: r.append(ch)
        else: r.append(".")
    return "".join(r)

files, dirs = T.collect_repaired(r"F:\@AI-workshop\rwmod\5.rwmod")
orig = {name: data for name, data, mod in files}
zf = zipfile.ZipFile(r"F:\@AI-workshop\rwmod\RustedWarfare1.15\mods\units\5_modified.rwmod")
mod = {}
for n in zf.namelist():
    if n.endswith("/"): continue
    mod[n] = zf.read(n)

targets = [n for n in mod if b"@global KJMYoTI8RT" in mod[n]]
for n in targets:
    w("="*80)
    w("FILE:", vis(n))
    w("in original:", n in orig)
    so = T.parse_ini(orig.get(n, b"").decode("utf-8","replace"))
    sm = T.parse_ini(mod[n].decode("utf-8","replace"))
    w("orig sections:", len(so), "mod sections:", len(sm))
    w("orig section set == mod:",
      sorted(so.keys()) == sorted(sm.keys()))
    if sorted(so.keys()) != sorted(sm.keys()):
        w("  only-orig:", [vis(x) for x in so.keys() if x not in sm][:20])
        w("  only-mod :", [vis(x) for x in sm.keys() if x not in so][:20])
    # compare global keys
    def globals(secs):
        d = {}
        for sn, kv in secs.items():
            for k, v in kv.items():
                if k.startswith("@global") or k.startswith("@define") or k.startswith("@memory"):
                    d[(sn, k)] = v
        return d
    go, gm = globals(so), globals(sm)
    w("orig global count:", len(go), "mod global count:", len(gm))
    miss = set(go) - set(gm)
    extra = set(gm) - set(go)
    w("globals missing in mod:", len(miss))
    for x in list(miss)[:20]:
        w("   MISS", vis(x[0]), vis(x[1]))
    w("globals extra in mod:", len(extra))
    # check value diffs for common
    diff = 0
    for kk in set(go) & set(gm):
        if go[kk] != gm[kk]:
            diff += 1
            if diff <= 10:
                w("   VALDIFF", vis(kk[0]), vis(kk[1]), "| orig=", vis(go[kk])[:60], "| mod=", vis(gm[kk])[:60])
    w("global value diffs:", diff)
out.close()
print("done")

