def _as_config(name, data, require_known=False):
    """Parse a member as an INI config, or return None.

    With ``require_known`` the content must contain at least one section the
    engine recognises, which keeps binary files from being mistaken for ini.
    """
    text = _decode_maybe_text(data)
    if text is None:
        return None
    sections = parse_ini(text)
    if not sections:
        return None
    if require_known and not any(is_recognized_section(s) for s in sections):
        return None
    return sections


def _copyfrom_targets(sections):
    """Return the [core] copyFrom paths of one file."""
    core = sections.get("core")
    if not core:
        return []
    value = core.get("copyFrom")
    if not value or value.strip().upper() == "IGNORE":
        return []
    return [t.strip() for t in value.split(",") if t.strip()]


def build_config_sections(files, resolve, use_template, progress=None):
    """Parse (and optionally expand) every config file.

    Returns ``(sections_by_name, unresolved_count)``.  Without --resolve the
    sections are just the modified files; with --resolve they are the final
    effective content.

    A file is treated as a config when its name says so (.ini/.template/
    mod-info.txt) or when it is referenced by a ``[core] copyFrom`` (directly
    or transitively).  The latter also covers protected packs that store
    configs under obfuscated names without a normal extension.
    """
    by_name = {name: data for name, data, _ in files}
    member_names = list(by_name)
    root = detect_root(member_names)
    resolver = Resolver(OrderedDict(), root, use_template)
    resolver.index = FileIndex(member_names)

    parsed = OrderedDict()
    # pass 1: names that are config files, plus extensionless members whose
    # content parses as ini (protected packs hide configs this way)
    if progress:
        progress.phase("解析", len(files))
    for name, data, _ in files:
        if progress:
            progress.step()
        # Without --resolve-template the all-units.template files are left
        # untouched, so the engine keeps applying them at runtime.
        if resolve and not use_template and is_template_entry(name):
            continue
        if is_text_config(name):
            parsed[name] = parse_ini(read_text(data))
        elif "." not in name.rsplit("/", 1)[-1]:
            sections = _as_config(name, data, require_known=True)
            if sections is not None:
                parsed[name] = sections

    # pass 2: follow [core] copyFrom references transitively
    work = list(parsed)
    while work:
        name = work.pop()
        for target in _copyfrom_targets(parsed[name]):
            tname = resolver.resolve_target(target, name)
            if not tname or tname in parsed:
                continue
            if progress:
                progress.step()
            sections = _as_config(tname, by_name.get(tname, b""))
            if sections is not None:
                parsed[tname] = sections
                work.append(tname)

    if not resolve:
        return parsed, 0

    if progress:
        progress.phase("展开", len(parsed))
    resolver = Resolver(parsed, detect_root(parsed.keys()), use_template)
    out = OrderedDict()
    unresolved = 0
    for name in parsed:
        if progress:
            progress.step()
        sections = resolver.resolve(name)
        out[name] = sections
        if "${" in dump_ini(sections):
            unresolved += 1
    return out, unresolved


def process(in_path, out_dir=None, out_rwmod=None, modify_ini=True,
            list_only=False, add_dirs=True, resolve=False,
            resolve_template=False, keylist_mode=None, strip_invalid_keys=False,
            repair=False, progress=None):
    if progress is None:
        progress = Progress()
    stats = Stats()
    base = os.path.splitext(os.path.basename(in_path))[0]
    if out_rwmod is None:
        # Default: put the rwmod next to the input file.
        out_rwmod = os.path.join(
            os.path.dirname(os.path.abspath(in_path)),
            base + "_modified.rwmod")

    files = None
    if not repair:
        try:
            zf = open_zip(in_path)
            try:
                files, dirs = collect(zf, progress)
            finally:
                zf.close()
            stats.repaired = False
        except Exception:
            files = None
    if files is None:
        # Broken/mangled zip header -> use the repair reader.
        files, dirs = collect_repaired(in_path, progress)
        stats.repaired = True

    if list_only:
        for name, data, changed in files:
            tag = " (was disguised)" if changed else ""
            print("%10d  %s%s" % (len(data), name, tag))
        progress.finish()
        return stats

    # ---- modify / expand config files ------------------------------------
    if modify_ini:
        sections_by_name, stats.unresolved = build_config_sections(
            files, resolve, resolve_template, progress)
        stats.ini_files = len(sections_by_name)
        stats.ini_sections = sum(len(secs) for secs in sections_by_name.values())
        stats.ini_keys = sum(
            len(sec) for secs in sections_by_name.values() for sec in secs.values())
        stats.stripped = strip_unknown_sections(sections_by_name)
        member_names = [n for n, _, _ in files]
        stats.paths_fixed = normalize_reference_paths(
            sections_by_name, member_names, detect_root(member_names))

        # ---- key-name validity check (only on request) ----------------------
        if keylist_mode:
            text = None
            if keylist_mode == "external":
                path = find_external_keylist(in_path)
                if path:
                    text = read_text(open(path, "rb").read())
                    stats.keylist = path
                else:
                    print("warning: keyList.txt not found, key check skipped",
                          file=sys.stderr)
            else:
                try:
                    text = internal_keylist_text()
                    stats.keylist = "(internal)"
                except ValueError as exc:
                    print("warning: %s" % exc, file=sys.stderr)
            if text:
                validator = KeyValidator(text)
                invalid = validator.check(sections_by_name)
                stats.invalid_keys = len(invalid)
                for file_name, section, key in invalid:
                    stats.invalid_examples.append(
                        "%s [%s] %s" % (file_name, section, key))
                if strip_invalid_keys:
                    for file_name, section, key in invalid:
                        sections_by_name[file_name][section].pop(key, None)

        new_files = []
        for name, data, changed in files:
            if name in sections_by_name:
                data = dump_ini(sections_by_name[name]).encode("utf-8")
            new_files.append((name, data, changed))
        files = new_files

        if resolve and resolve_template:
            # all-units.template has been inlined into every unit, so the
            # template files themselves are removed from the output.
            before = len(files)
            files = [f for f in files if not is_template_entry(f[0])]
            stats.removed_templates = before - len(files)

    # ---- write output folder -------------------------------------------------
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
        progress.phase("写出", len(files))
    for name, data, changed in files:
        if changed:
            stats.renamed += 1
        stats.files += 1
        if out_dir:
            dest = safe_member_path(out_dir, name)
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest, "wb") as fh:
                fh.write(data)
            progress.step()

    # ---- repack a standard rwmod --------------------------------------------
    all_dirs = set(dirs)
    for name, _, _ in files:
        parts = name.split("/")[:-1]
        acc = ""
        for p in parts:
            acc = acc + "/" + p if acc else p
            all_dirs.add(acc)
    dir_list = [d for d in sorted(all_dirs) if d]

    out_path = out_rwmod
    if out_path:
        parent = os.path.dirname(os.path.abspath(out_path))
        if parent:
            os.makedirs(parent, exist_ok=True)
        total = len(files) + (len(dir_list) if add_dirs else 0)
        progress.phase("打包", total)
        with zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as zo:
            if add_dirs:
                for d in dir_list:
                    zi = zipfile.ZipInfo(d + "/")
                    zi.compress_type = zipfile.ZIP_STORED
                    zi.external_attr = 0o40755 << 16
                    zo.writestr(zi, b"")
                    progress.step()
            for name, data, changed in files:
                zi = zipfile.ZipInfo(name)
                zi.compress_type = zipfile.ZIP_DEFLATED
                zi.external_attr = 0o100644 << 16
                # 0x800 = UTF-8 flag, set by zipfile when needed automatically
                zo.writestr(zi, data)
                progress.step()
        stats.out_rwmod = out_path

