def w(*a): out.write(" ".join(str(x) for x in a) + "\n")
def vis(s): return "".join(ch if 0x20<=ord(ch)<0x7f else "." for ch in s)

def parse_keep_toplevel(text):
    """Like parse_ini but keeps pre-section keys in a '' bucket and records order."""
    text = text.replace("\ufeff", "")
    lines = re.split(r"\r\n|\r|\n", text)
    order = []   # (section, key, value)
    current = ""
    i = 0; n = len(lines)
    while i < n:
        raw = lines[i]; i += 1
        s = raw.strip()
        if s == "" or s[0] == "#":
            continue
        skip = (s[0] == '"')
        in_quotes = False; buf = []; piece = s
        while True:
            j = 0; ln = len(piece)
            while j >= 0:
                k = piece.find('"""', j)
                if k < 0:
                    m = k; k = ln
                else:
                    in_quotes = not in_quotes; m = k + 3
                if not skip: buf.append(piece[j:k])
                j = m
            if in_quotes:
                if i >= n: break
                piece = lines[i].strip(); i += 1
            else:
                break
        if skip: continue
        s = "".join(buf)
        if s == "": continue
        if s[0] == "[":
            close = s.find("]", 1)
            if close == len(s)-1:
                name = s[1:close].strip()
                current = "" if name.startswith("comment_") else name
                continue
        split = -1
        for idx, ch in enumerate(s):
            if ch==":" or ch=="=":
                split = idx; break
        if split < 0: continue
        order.append((current, s[:split].strip(), s[split+1:].strip()))
    return order

files, dirs = T.collect_repaired(r"F:\@AI-workshop\rwmod\5.rwmod")
orig = {n: d for n,d,_ in files}

# find where a given token is defined in original
def find_defs(token):
    res = []
    for name, data in orig.items():
        txt = data.decode("utf-8","replace")
        if '"' not in txt and "global" not in txt and token not in txt:
            continue
        try:
            order = parse_keep_toplevel(txt)
        except Exception:
            continue
        for idx,(sec,k,v) in enumerate(order):
            if k.startswith("@global") or k.startswith("@define"):
                vn = k.split(None,1)[1] if " " in k else ""
                if vn == token:
                    res.append((name, sec, k, v, idx, order[:idx].count(None)))
    return res

for token in sys.argv[1:]:
