pathglobals = {}
for n,d,_ in files:
    s = T.parse_ini(d.decode("utf-8","replace"))
    for sec, kv in s.items():
        for k, v in kv.items():
            if k.startswith("@global ") or k.startswith("@define "):
                name = k.split(" ",1)[1]
                vv = v.strip()
                if vv.endswith("/") or ".ini/" in vv or vv.endswith(".ini"):
                    pathglobals.setdefault(name, []).append((n, vis(k), vis(v)[:120]))

